        def test_creation_is_income_and_items_keep_same_number(self):
            inv=self.db.create_inventory('Artes',self.bogota,responsible='Ana',destination='Taller de artes',
                suppliers=[{'name':'Pinturas Uno','nit':'900.123.456-7'},{'name':'Pinceles Dos','nit':'901222333-4'}])
            head=self.db.inventory_income(inv);count=len(self.db.receipts('INGRESO'))
            self.assertEqual(self.db.receipt(head['id'])[1],[])
            self.assertTrue(any(f['id']==head['id'] for f in self.db.receipts('INGRESO',inventory_id=inv)))
            self.db.add_inventory_items(inv,[{'name':'pincel','amount':4},{'name':'lienzo','amount':6}])
            self.db.create_product(inv,'Pintura',10)
            current,lines=self.db.receipt(head['id'])
